public class Main {
    static String repeat(char c, int times) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < times; i++) {
            sb.append(c);
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        int rows = 3;
        for (int i = 1; i <= rows; i++) {
            System.out.println(repeat(' ', rows - i) + repeat('*', 2 * i - 1));
        }
    }
}
